//! IPv6 formatting/parsing and small RTL compatibility routines.
use super::{AnsiString, UnicodeString};
const SUCCESS:i32=0; const INVALID:i32=0xC000000Du32 as i32; const SMALL:i32=0xC0000023u32 as i32;
fn parse_hex_group(s:&[u8])->Option<u16>{if s.is_empty()||s.len()>4{return None;}let mut v=0u16;for &c in s{let d=match c{b'0'..=b'9'=>c-b'0',b'a'..=b'f'=>c-b'a'+10,b'A'..=b'F'=>c-b'A'+10,_=>return None};v=(v<<4)|d as u16;}Some(v)}
fn parse_ipv6_core(s:&[u8])->Option<[u8;16]>{if s.is_empty(){return None;}let mut g=[0u16;8];let(mut count,mut i,mut compress)=(0usize,0usize,None);if s.starts_with(b"::"){compress=Some(0);i=2;}while i<s.len(){if count>=8{return None;}let st=i;while i<s.len()&&s[i]!=b':'{i+=1;}let t=&s[st..i];if t.contains(&b'.'){if count>6{return None;}let mut oct=[0u8;4];let mut p=0;for k in 0..4{let start=p;let mut v=0u32;while p<t.len()&&t[p].is_ascii_digit(){v=v*10+(t[p]-b'0') as u32;if v>255{return None;}p+=1;}if p==start{return None;}oct[k]=v as u8;if k<3{if p>=t.len()||t[p]!=b'.'{return None;}p+=1;}}if p!=t.len()||i!=s.len(){return None;}g[count]=u16::from_be_bytes([oct[0],oct[1]]);g[count+1]=u16::from_be_bytes([oct[2],oct[3]]);count+=2;break;}g[count]=parse_hex_group(t)?;count+=1;if i<s.len(){i+=1;if i<s.len()&&s[i]==b':'{if compress.is_some(){return None;}compress=Some(count);i+=1;if i==s.len(){break;}}else if i==s.len(){return None;}}}if let Some(at)=compress{if count>=8{return None;}let z=8-count;for j in (at..count).rev(){g[j+z]=g[j];}for j in at..at+z{g[j]=0;}count=8;}if count!=8{return None;}let mut out=[0u8;16];for j in 0..8{out[j*2..j*2+2].copy_from_slice(&g[j].to_be_bytes());}Some(out)}
fn format_ipv6(a:&[u8;16],out:&mut [u8;48])->usize{let mut g=[0u16;8];for i in 0..8{g[i]=u16::from_be_bytes([a[i*2],a[i*2+1]]);}let(mut bs,mut bl)=(8usize,1usize);let mut i=0;while i<8{if g[i]!=0{i+=1;continue;}let st=i;while i<8&&g[i]==0{i+=1;}if i-st>bl{bs=st;bl=i-st;}}let(mut p,mut j)=(0usize,0usize);while j<8{if j==bs{out[p]=b':';p+=1;out[p]=b':';p+=1;j+=bl;if j==8{break;}continue;}if p>0&&out[p-1]!=b':'{out[p]=b':';p+=1;}let mut started=false;for sh in [12u32,8,4,0]{let d=((g[j]>>sh)&15) as u8;if d!=0||started||sh==0{out[p]=if d<10{b'0'+d}else{b'a'+d-10};p+=1;started=true;}}j+=1;}p}
unsafe fn addr_a(a:*const u8,d:*mut u8)->*mut u8{if a.is_null()||d.is_null(){return core::ptr::null_mut();}let mut x=[0u8;16];unsafe{core::ptr::copy_nonoverlapping(a,x.as_mut_ptr(),16);}let mut b=[0u8;48];let n=format_ipv6(&x,&mut b);unsafe{core::ptr::copy_nonoverlapping(b.as_ptr(),d,n);*d.add(n)=0;d.add(n)}}
unsafe fn addr_w(a:*const u8,d:*mut u16)->*mut u16{if a.is_null()||d.is_null(){return core::ptr::null_mut();}let mut x=[0u8;16];unsafe{core::ptr::copy_nonoverlapping(a,x.as_mut_ptr(),16);}let mut b=[0u8;48];let n=format_ipv6(&x,&mut b);for i in 0..n{unsafe{*d.add(i)=b[i] as u16;}}unsafe{*d.add(n)=0;d.add(n)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ipv6_address_to_string_a(a:*const u8,d:*mut u8)->*mut u8{unsafe{addr_a(a,d)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ipv6_address_to_string_w(a:*const u8,d:*mut u16)->*mut u16{unsafe{addr_w(a,d)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ipv6_address_to_string_ex_a(a:*const u8,scope:u32,port:u16,d:*mut u8,len:*mut u32)->i32{if a.is_null()||d.is_null()||len.is_null(){return INVALID;}let mut x=[0u8;16];unsafe{core::ptr::copy_nonoverlapping(a,x.as_mut_ptr(),16);}let mut b=[0u8;80];let mut p=0; b[p]=b'[';p+=1;let mut inner=[0u8;48];let n=format_ipv6(&x,&mut inner);b[p..p+n].copy_from_slice(&inner[..n]);p+=n;if scope!=0{b[p]=b'%';p+=1;let mut tmp=[0u8;10];let mut k=0;let mut v=scope;loop{tmp[k]=b'0'+(v%10) as u8;k+=1;v/=10;if v==0{break;}}for j in (0..k).rev(){b[p]=tmp[j];p+=1;}}b[p]=b']';p+=1;if port!=0{b[p]=b':';p+=1;let mut tmp=[0u8;5];let mut k=0;let mut v=port;loop{tmp[k]=b'0'+(v%10) as u8;k+=1;v/=10;if v==0{break;}}for j in (0..k).rev(){b[p]=tmp[j];p+=1;}}if (unsafe{*len} as usize)<p+1{unsafe{*len=(p+1) as u32;}return SMALL;}unsafe{core::ptr::copy_nonoverlapping(b.as_ptr(),d,p);*d.add(p)=0;*len=(p+1) as u32;}SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ipv6_address_to_string_ex_w(a:*const u8,scope:u32,port:u16,d:*mut u16,len:*mut u32)->i32{if a.is_null()||d.is_null()||len.is_null(){return INVALID;}let mut b=[0u8;80];let mut n=80u32;let st=unsafe{rtl_ipv6_address_to_string_ex_a(a,scope,port,b.as_mut_ptr(),&mut n)};if st!=SUCCESS{return st;}let chars=(n-1) as usize;if (unsafe{*len} as usize)<chars+1{unsafe{*len=(chars+1) as u32;}return SMALL;}for i in 0..chars{unsafe{*d.add(i)=b[i] as u16;}}unsafe{*d.add(chars)=0;*len=(chars+1) as u32;}SUCCESS}
unsafe fn parse_a(s:*const u8,term:*mut *const u8,a:*mut u8)->i32{if s.is_null()||term.is_null()||a.is_null(){return INVALID;}let mut n=0;while n<128&&unsafe{*s.add(n)}!=0{n+=1;}if n==128{return INVALID;}let b=unsafe{core::slice::from_raw_parts(s,n)};let mut end=n;while end>0&&b[end-1].is_ascii_whitespace(){end-=1;}let mut st=0;while st<end&&b[st].is_ascii_whitespace(){st+=1;}let end=b[st..end].iter().position(|c|*c==b'%').map(|x|st+x).unwrap_or(end);let Some(x)=parse_ipv6_core(&b[st..end])else{return INVALID;};unsafe{core::ptr::copy_nonoverlapping(x.as_ptr(),a,16);*term=s.add(end);}SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ipv6_string_to_address_a(s:*const u8,t:*mut *const u8,a:*mut u8)->i32{unsafe{parse_a(s,t,a)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ipv6_string_to_address_w(s:*const u16,t:*mut *const u16,a:*mut u8)->i32{if s.is_null()||t.is_null()||a.is_null(){return INVALID;}let mut b=[0u8;128];let mut n=0;while n<128{let c=unsafe{*s.add(n)};if c==0{break;}if c>127{return INVALID;}b[n]=c as u8;n+=1;}if n==128{return INVALID;}b[n]=0;let mut p=core::ptr::null();let st=unsafe{parse_a(b.as_ptr(),&mut p,a)};if st==SUCCESS{unsafe{*t=s.add(p as usize-b.as_ptr() as usize);}}st}
unsafe fn parse_ex(s:*const u8,a:*mut u8,scope:*mut u32,port:*mut u16)->i32{if s.is_null()||a.is_null()||scope.is_null()||port.is_null(){return INVALID;}let mut n=0;while n<160&&unsafe{*s.add(n)}!=0{n+=1;}if n==160{return INVALID;}let b=unsafe{core::slice::from_raw_parts(s,n)};let(mut lo,mut hi)=(0usize,n);while lo<hi&&b[lo].is_ascii_whitespace(){lo+=1;}while hi>lo&&b[hi-1].is_ascii_whitespace(){hi-=1;}if hi-lo>=2&&b[lo]==b'['&&b[hi-1]==b']'{lo+=1;hi-=1;}let(mut pv,mut sv)=(0u32,0u32);let mut end=hi;if let Some(c)=b[lo..hi].iter().rposition(|x|*x==b':'){if lo+c+1<hi&&b[lo+c+1..hi].iter().all(|x|x.is_ascii_digit()){for x in &b[lo+c+1..hi]{pv=pv.saturating_mul(10).saturating_add((*x-b'0') as u32);if pv>65535{return INVALID;}}end=lo+c;}}let mut aend=end;if let Some(p)=b[lo..end].iter().position(|x|*x==b'%'){let at=lo+p;if at+1>=end{return INVALID;}for x in &b[at+1..end]{if !x.is_ascii_digit(){return INVALID;}sv=sv.saturating_mul(10).saturating_add((*x-b'0') as u32);}aend=at;}let Some(x)=parse_ipv6_core(&b[lo..aend])else{return INVALID;};unsafe{core::ptr::copy_nonoverlapping(x.as_ptr(),a,16);*scope=sv;*port=pv as u16;}SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ipv6_string_to_address_ex_a(s:*const u8,a:*mut u8,scope:*mut u32,port:*mut u16)->i32{unsafe{parse_ex(s,a,scope,port)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_ipv6_string_to_address_ex_w(s:*const u16,a:*mut u8,scope:*mut u32,port:*mut u16)->i32{if s.is_null(){return INVALID;}let mut b=[0u8;160];let mut n=0;while n<160{let c=unsafe{*s.add(n)};if c==0{break;}if c>127{return INVALID;}b[n]=c as u8;n+=1;}if n==160{return INVALID;}b[n]=0;unsafe{parse_ex(b.as_ptr(),a,scope,port)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_duplicate_unicode_string(flags:u32,src:*const UnicodeString,dst:*mut UnicodeString)->i32{if src.is_null()||dst.is_null()||flags&!3!=0{return INVALID;}let s=unsafe{&*src};let d=unsafe{&mut *dst};if s.length%2!=0||s.length>s.maximum_length||(s.length>0&&s.buffer.is_null()){return INVALID;}let nul=flags&1!=0;let empty=flags&2!=0;if s.length==0&&!empty{d.length=0;d.maximum_length=0;d.buffer=core::ptr::null_mut();return SUCCESS;}let Some(cap)=(s.length as usize).checked_add(if nul{2}else{0})else{return SMALL;};if cap>u16::MAX as usize{return SMALL;}let p=super::pool::allocate(cap.max(2));if p.is_null(){return SMALL;}if s.length>0{unsafe{core::ptr::copy_nonoverlapping(s.buffer,p.cast::<u16>(),(s.length/2) as usize);}}if nul{unsafe{*p.cast::<u16>().add((s.length/2) as usize)=0;}}d.buffer=p.cast::<u16>();d.length=s.length;d.maximum_length=cap.max(2) as u16;SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_string_from_guid_ex(g:*const super::network::RtlGuid,dst:*mut UnicodeString,allocate:u8)->i32{if g.is_null()||dst.is_null(){return INVALID;}let d=unsafe{&mut *dst};if allocate!=0{let p=super::pool::allocate(78);if p.is_null(){return SMALL;}d.buffer=p.cast::<u16>();d.maximum_length=78;d.length=0;}let st=unsafe{super::network::rtl_string_from_guid(g,dst)};if st!=SUCCESS&&allocate!=0{let _=super::pool::deallocate(d.buffer.cast::<u8>());d.buffer=core::ptr::null_mut();d.maximum_length=0;d.length=0;}st}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_get_enabled_extended_and_supervisor_features(_mask:u64)->u64{0}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_prefetch_memory_non_temporal(p:*const core::ffi::c_void,n:usize){if p.is_null()||n==0{return;}#[cfg(target_arch="x86_64")] unsafe{core::arch::x86_64::_mm_prefetch(p.cast::<i8>(),core::arch::x86_64::_MM_HINT_NTA);}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_interlocked_set_clear_run(b:*mut super::RtlBitmap,start:u32,set_count:u32,clear_count:u32){if b.is_null(){return;}unsafe{super::bitmap_abi::rtl_interlocked_set_bit_run(b,start,set_count);}if let Some(clear_start)=start.checked_add(set_count){unsafe{super::bitmap_abi::rtl_interlocked_clear_bit_run(b,clear_start,clear_count);}}}
#[cfg(test)] mod tests{use super::*;#[test]fn ipv6_roundtrip(){let a=parse_ipv6_core(b"2001:db8::1").unwrap();let mut b=[0u8;48];let n=format_ipv6(&a,&mut b);assert_eq!(&b[..n],b"2001:db8::1");assert_eq!(parse_ipv6_core(&b[..n]),Some(a));}#[test]fn ipv6_zero_loopback(){assert_eq!(parse_ipv6_core(b"::"),Some([0;16]));assert_eq!(parse_ipv6_core(b"::1").unwrap()[15],1);}}
